/// The methods `qualified` and its ancestors define, `None` when it is not listed.
pub fn methods(qualified: &str) -> Option<&'static [&'static str]> {
    CLASS_METHODS
        .binary_search_by_key(&qualified, |(class, _)| class)
        .ok()
        .map(|at| CLASS_METHODS[at].1)
}
